; Rigs of Rods input map for the "Phone Controllers Wheel" virtual joystick (this repo's server.py).
; Install: copy to ~/.rigsofrods/config/Phone_Controllers_Wheel.map and restart the game.
;
; OIS axes: 0 steering, 1 gas, 2 brake, 3 clutch. Pedals run -1 (released) .. +1 (pressed),
; which Rigs of Rods maps to 0..1 when no LOWER/UPPER region is given.
; Buttons follow the phone layout: 0 Shift-, 1 Shift+, 2 Handbrake, 3 Horn, 4 Lights,
; 5 Camera, 6 Look back, 7 Wipers (ignition switch here), 8 Ignition (starter), 9 Hazard,
; 10 Map, 11 Pause, 12 Left signal, 13 Right signal.

; TRUCK
TRUCK_STEER_LEFT               JoystickAxis         0 0 LOWER+DEADZONE=0.00
TRUCK_STEER_RIGHT              JoystickAxis         0 0 UPPER+DEADZONE=0.00
TRUCK_ACCELERATE               JoystickAxis         0 1 DEADZONE=0.00
TRUCK_BRAKE                    JoystickAxis         0 2 DEADZONE=0.00
TRUCK_MANUAL_CLUTCH            JoystickAxis         0 3 DEADZONE=0.00
TRUCK_SHIFT_DOWN               JoystickButton       0 0
TRUCK_AUTOSHIFT_DOWN           JoystickButton       0 0
TRUCK_SHIFT_UP                 JoystickButton       0 1
TRUCK_AUTOSHIFT_UP             JoystickButton       0 1
TRUCK_PARKING_BRAKE            JoystickButton       0 2
TRUCK_HORN                     JoystickButton       0 3
TRUCK_TOGGLE_CONTACT           JoystickButton       0 7
TRUCK_STARTER                  JoystickButton       0 8
TRUCK_BLINK_WARN               JoystickButton       0 9
TRUCK_BLINK_LEFT               JoystickButton       0 12
TRUCK_BLINK_RIGHT              JoystickButton       0 13

; BOAT
BOAT_STEER_LEFT_AXIS           JoystickAxis         0 0 LOWER+DEADZONE=0.00
BOAT_STEER_RIGHT_AXIS          JoystickAxis         0 0 UPPER+DEADZONE=0.00
BOAT_THROTTLE_AXIS             JoystickAxis         0 1 DEADZONE=0.00

; COMMON
COMMON_TOGGLE_TRUCK_LOW_BEAMS  JoystickButton       0 4
CAMERA_CHANGE                  JoystickButton       0 5
CAMERA_LOOKBACK                JoystickButton       0 6
SURVEY_MAP_TOGGLE              JoystickButton       0 10
COMMON_QUIT_GAME               JoystickButton       0 11
